/**
 * @public
 */
export interface RadarPoint {
  x: number;
  y: number;
  cx?: number;
  cy?: number;
  angle: number;
  radius?: number;
  value?: number;
  payload?: any;
  name?: string | number;
}

/**
 * The type is exported only so that TypeScript can name it in the declaration files of projects
 * that wrap Recharts components. It is not part of the public API and may change in any release.
 *
 * @internal
 */
export interface RadarProps<DataPointType = any, DataValueType = any>
  extends ZIndexable, ValueAxisDataConsumer<DataPointType, DataValueType> {
  /**
   * The fill of the radar polygon. Either a color string, or a {@link RechartsFill} object with an SVG definition,
   * such as a pattern or a gradient.
   *
   * With a fill object, Recharts renders the definition with a unique ID, in the chart and in the Legend icon.
   * Tooltip, labels, and dots use the solid `color` of the fill object.
   * If the fill object has no `color`, the radar keeps the theme colors and the definition gets the theme color.
   *
   * @example <Radar fill={{ definition: pattern(patterns.diagonal) }} />
   */
  fill?: string | RechartsFill;
  /**
   * @defaultValue true
   */
  activeDot?: ActiveDotType;
  /**
   * @defaultValue 0
   */
  angleAxisId?: string | number;
  /**
   * Specifies when the animation should begin, the unit of this option is ms.
   * @defaultValue 0
   */
  animationBegin?: number;
  /**
   * Specifies the duration of animation, the unit of this option is ms.
   * @defaultValue 1500
   */
  animationDuration?: AnimationDuration;
  /**
   * The type of easing function.
   * @defaultValue ease
   */
  animationEasing?: EasingInput;
  /**
   * Custom animation function for interpolating data items.
   * When provided, this replaces the default animation interpolation.
   *
   * @param prevItems The items from the previous animation frame, or null on first render
   * @param nextItems The target items to animate towards
   * @param animationElapsedTime A normalized time value (0 = start, 1 = end)
   * @returns The interpolated items at time animationElapsedTime
   *
   * @since 3.9
   * @see {@link https://recharts.github.io/en-US/guide/animations/ Animations guide}
   */
  animationInterpolateFn?: AnimationInterpolateFn<RadarPoint, PolarLayout>;
  /**
   * Strategy for matching previous items to next items during animation.
   * Determines how Recharts pairs old data points with new data points
   * to create smooth transitions.
   *
   * - `matchByIndex` (default): match by array position with proportional stretching
   * - `matchAppend`: match sequentially by index and treat newly appended items as new
   * - `matchByDataKey('someKey')`: match by a data key from the payload
   * - Custom function `(item, index) => key`: match by the returned key
   *
   * @defaultValue index
   * @see matchByIndex
   * @see matchByDataKey
   * @see matchAppend
   */
  animationMatchBy?: AnimationMatchByProp<RadarPoint>;
  baseLinePoints?: RadarPoint[];
  className?: string;
  connectNulls?: boolean;
  /**
   * Renders a dot at each data point. Options:
   *
   * - `false`: no dots are drawn;
   * - `true`: renders the dots with default settings;
   * - `object`: the props of the dot. This will be merged with the internal calculated props of each dot.
   *   Set `symbol` to draw a predefined symbol instead of a circle;
   * - `ReactElement`: the custom dot element;
   * - `function`: a render function of the custom dot.
   *   The legend cannot know what a custom element or function draws, so set a matching `legendType`;
   * - `string`: name of a predefined symbol, such as `'diamond'` or `'star'`, the same as in `legendType`.
   *   Use different symbols to tell series apart without relying on color.
   *   The legend icon shows the same symbol.
   *   To change the size of the symbol, use the object form with `symbol` and `r`.
   *
   * @defaultValue false
   */
  dot?: DotType;
  /**
   * @defaultValue false
   */
  hide?: boolean;
  /**
   * If set false, animation of polygon will be disabled.
   * If set "auto", the animation will be disabled in SSR and will respect the user's prefers-reduced-motion system preference for accessibility.
   * @defaultValue auto
   */
  isAnimationActive?: boolean | 'auto';
  isRange?: boolean;
  /**
   * Renders one label for each point. Options:
   * - `true`: renders default labels;
   * - `false`: no labels are rendered;
   * - `object`: the props of LabelList component;
   * - `ReactElement`: a custom SVG label element, such as `<text>` or `<g>`.
   *   HTML elements such as `<div>` are not valid inside the chart SVG and may trigger React DOM warnings.
   * - `function`: a render function of custom label.
   *
   * @defaultValue false
   */
  label?: ImplicitLabelListType;
  /**
   * The type of icon in legend.
   * If set to 'none', no legend item will be rendered.
   *
   * By default, the legend icon shows the same predefined symbol as the data points, if they use one.
   *
   * @defaultValue rect
   */
  legendType?: LegendType;
  /**
   * The customized event handler of animation end
   */
  onAnimationEnd?: () => void;
  /**
   * The customized event handler of animation start
   */
  onAnimationStart?: () => void;
  onMouseEnter?: (props: InternalRadarProps, e: MouseEvent<SVGPolygonElement>) => void;
  onMouseLeave?: (props: InternalRadarProps, e: MouseEvent<SVGPolygonElement>) => void;
  /**
   * @defaultValue 0
   */
  radiusAxisId?: string | number;

  /**
   * If set a ReactElement, the shape of radar can be customized.
   * If set a function, the function will be called to render customized shape.
   */
  shape?: ReactElement<SVGElement> | ((props: any) => ReactElement<SVGElement>);
  tooltipType?: TooltipType;
  /**
   * Z-Index of this component and its children. The higher the value,
   * the more on top it will be rendered.
   * Components with higher zIndex will appear in front of components with lower zIndex.
   * If undefined or 0, the content is rendered in the default layer without portals.
   *
   * @since 3.4
   * @defaultValue 100
   * @see {@link https://recharts.github.io/en-US/guide/zIndex/ Z-Index and layers guide}
   */
  zIndex?: number;
}

export type RadiusAxisForRadar = { scale: RechartsScale };
export type AngleAxisForRadar = {
  scale: RechartsScale;
  type: 'number' | 'category';
  dataKey: DataKey<any> | undefined;
  cx: number;
  cy: number;
  range: AxisRange;
};

/**
 * @public
 */
export type Props<DataPointType = any, DataValueType = any> = Omit<
  SVGProps<SVGGraphicsElement>,
  'onMouseEnter' | 'onMouseLeave' | 'points' | 'ref' | 'fill'
> &
  RadarProps<DataPointType, DataValueType>;

/**
 * Props after the fill object is split off: `fill` is the base color.
 */
type StringFillProps = Omit<Props, 'fill'> & { fill?: string };

export type RadarComposedData = {
  points: RadarPoint[];
  baseLinePoints: RadarPoint[];
  isRange: boolean;
};

function getLegendItemColor(stroke: string | undefined, fill: string | undefined): string | undefined {
  return stroke && stroke !== 'none' ? stroke : fill;
}

const computeLegendPayloadFromRadarSectors = (
  props: PropsWithDefaults,
  dotFill: string | undefined,
  fillObject: RechartsFill | undefined,
): ReadonlyArray<LegendPayload> => {
  const { dataKey, name, stroke, fill, legendType, hide, dot } = props;
  return [
    {
      inactive: hide,
      dataKey,
      type: legendType,
      // the same colors as the dots get in RadarDotsWrapper
      // Radar keeps its default legend icons with a theme too, only a dot symbol changes them
      dot: getLegendPayloadDot(dot, { fill: dotFill ?? fill, stroke }, false),
      color: getLegendItemColor(stroke, fill),
      fill: fillObject,
      value: getTooltipNameProp(name, dataKey),
      payload: props,
    },
  ];
};

const SetRadarTooltipEntrySettings = React.memo(
  ({
    dataKey,
    stroke,
    strokeWidth,
    fill,
    name,
    hide,
    tooltipType,
    id,
  }: Pick<
    WithIdRequired<PropsWithDefaults>,
    'dataKey' | 'stroke' | 'strokeWidth' | 'fill' | 'name' | 'hide' | 'tooltipType' | 'id'
  >) => {
    const tooltipEntrySettings: TooltipPayloadConfiguration = {
      /*
       * I suppose this here _could_ return props.points
       * because while Radar does not support item tooltip mode, it _could_ support it.
       * But when I actually do return the points here, a defaultIndex test starts failing.
       * So, undefined it is.
       */
      dataDefinedOnItem: undefined,
      getPosition: noop,
      settings: {
        stroke,
        strokeWidth,
        fill,
        nameKey: undefined, // RadarChart does not have nameKey unfortunately
        dataKey,
        name: getTooltipNameProp(name, dataKey),
        hide,
        type: tooltipType,
        color: getLegendItemColor(stroke, fill),
        unit: '', // why doesn't Radar support unit?
        graphicalItemId: id,
        ignoreDataEntryColors: true,
      },
    };
    return <SetTooltipEntrySettings tooltipEntrySettings={tooltipEntrySettings} />;
  },
);

type RadarPropsWithDotFill = WithIdRequired<PropsWithDefaults> & {
  dotFill?: string;
  /**
   * The fill object of the radar, from props or from the theme. The polygon paints with its definition.
   */
  fillObject?: RechartsFill;
  unthemedColors?: UnthemedColors;
  themedActiveStyles?: ColorStyles2D;
};

function RadarDotsWrapper({ points, props }: { points: ReadonlyArray<RadarPoint>; props: RadarPropsWithDotFill }) {
  const { dot, dataKey } = props;
  const { id, dotFill, unthemedColors, ...propsWithoutId } = props;

  const baseProps = svgPropertiesNoEvents(propsWithoutId);

  return (
    <Dots
      points={points}
      dot={dot}
      className="recharts-radar-dots"
      dotClassName="recharts-radar-dot"
      dataKey={dataKey}
      baseProps={{ ...baseProps, fill: dotFill ?? baseProps.fill }}
      unthemedColors={unthemedColors}
    />
  );
}

export function computeRadarPoints({
  radiusAxis,
  angleAxis,
  displayedData,
  dataKey,
  bandSize,
}: {
  radiusAxis: RadiusAxisForRadar;
  angleAxis: AngleAxisForRadar;
  displayedData: any[];
  dataKey: RadarProps['dataKey'];
  bandSize: number;
}): RadarComposedData {
  const { cx, cy } = angleAxis;
  let isRange = false;
  const points: RadarPoint[] = [];
  // scaleBand reverses the values it emits for a descending range, so only a descending range needs
  // the band offset that lands the first category on startAngle, same as angle axis ticks.
  const isDescending = angleAxis.range[0] > angleAxis.range[1];
  const angleBandSize = angleAxis.type !== 'number' && isDescending ? (bandSize ?? 0) : 0;

  displayedData.forEach((entry, i) => {
    const name = getValueByDataKey(entry, angleAxis.dataKey, i);
    const value = getValueByDataKey(entry, dataKey);
    const angle: number = (angleAxis.scale.map(name) ?? 0) + angleBandSize;
    const pointValue = Array.isArray(value) ? last(value) : value;
    // A missing value has no position: NaN coordinates make Polygon leave a gap there and Dot skip it.
    const radius: number = isNullish(pointValue) ? NaN : (radiusAxis.scale.map(pointValue) ?? 0);

    if (Array.isArray(value) && value.length >= 2) {
      isRange = true;
    }

    points.push({
      ...polarToCartesian(cx, cy, radius, angle),
      // getValueByDataKey does not validate the output type
      name,
      // getValueByDataKey does not validate the output type
      value,
      cx,
      cy,
      radius,
      angle,
      payload: entry,
    });
  });
  const baseLinePoints: RadarPoint[] = [];

  if (isRange) {
    points.forEach((point: RadarPoint) => {
      if (Array.isArray(point.value)) {
        const baseValue = point.value[0];
        const radius: number = isNullish(baseValue) ? NaN : (radiusAxis.scale.map(baseValue) ?? 0);

        baseLinePoints.push({
          ...point,
          radius,
          ...polarToCartesian(cx, cy, radius, point.angle),
        });
      } else {
        baseLinePoints.push(point);
      }
    });
  }

  return { points, isRange, baseLinePoints };
}

function RadarLabelListProvider({
  showLabels,
  points,
  children,
}: {
  showLabels: boolean;
  points: ReadonlyArray<RadarPoint>;
  children: ReactNode;
}) {
  /*
   * Radar provides a Cartesian label list context. Do we want to also provide a polar label list context?
   * That way, users can choose to use polar positions for the Radar labels.
   */
  // const labelListEntries: ReadonlyArray<PolarLabelListEntry> = points.map(
  //   (point): PolarLabelListEntry => ({
  //     value: point.value,
  //     payload: point.payload,
  //     parentViewBox: undefined,
  //     clockWise: false,
  //     viewBox: {
  //       cx: point.cx,
  //       cy: point.cy,
  //       innerRadius: point.radius,
  //       outerRadius: point.radius,
  //       startAngle: point.angle,
  //       endAngle: point.angle,
  //       clockWise: false,
  //     },
  //   }),
  // );

  const labelListEntries: ReadonlyArray<CartesianLabelListEntry> = points.map((point): CartesianLabelListEntry => {
    const viewBox: TrapezoidViewBox = {
      x: point.x,
      y: point.y,
      width: 0,
      lowerWidth: 0,
      upperWidth: 0,
      height: 0,
    };
    return {
      ...viewBox,
      value: point.value ?? '',
      payload: point.payload,
      parentViewBox: undefined,
      viewBox,
      fill: undefined,
    };
  });

  return (
    <CartesianLabelListContextProvider value={showLabels ? labelListEntries : undefined}>
      {children}
    </CartesianLabelListContextProvider>
  );
}

function StaticPolygon({
  points,
  baseLinePoints,
  props,
}: {
  points: ReadonlyArray<RadarPoint>;
  baseLinePoints: ReadonlyArray<RadarPoint>;
  props: InternalRadarProps;
}) {
  if (points == null) {
    return null;
  }

  const { shape, isRange, connectNulls, dotFill: _, fillObject, ...propsWithoutDotFill } = props;
  const paintFill = fillObject == null ? props.fill : getFillUrl(getSeriesFillId(props.id));

  const handleMouseEnter = (e: MouseEvent<SVGPolygonElement>) => {
    const { onMouseEnter } = props;

    if (onMouseEnter) {
      onMouseEnter(props, e);
    }
  };

  const handleMouseLeave = (e: MouseEvent<SVGPolygonElement>) => {
    const { onMouseLeave } = props;

    if (onMouseLeave) {
      onMouseLeave(props, e);
    }
  };

  let radar;
  if (React.isValidElement(shape)) {
    radar = React.cloneElement(shape, { ...propsWithoutDotFill, fill: paintFill, points } as any);
  } else if (typeof shape === 'function') {
    radar = shape({ ...propsWithoutDotFill, fill: paintFill, points });
  } else {
    radar = (
      <Polygon
        {...svgPropertiesAndEvents(props)}
        fill={paintFill}
        onMouseEnter={handleMouseEnter}
        onMouseLeave={handleMouseLeave}
        points={points}
        baseLinePoints={isRange ? baseLinePoints : undefined}
        connectNulls={connectNulls}
      />
    );
  }

  return (
    <Layer className="recharts-radar-polygon">
      {radar}
      <RadarDotsWrapper props={props} points={points} />
    </Layer>
  );
}

const defaultRadarAnimateItems: AnimationInterpolateFn<RadarPoint, PolarLayout> = (items, animationElapsedTime) => {
  if (items == null) return [];
  if (animationElapsedTime === 1) {
    return items.flatMap(item => (item.status === 'removed' ? [] : [item.next]));
  }
  return items.flatMap(item => {
    if (item.status === 'removed') return [];
    if (item.status === 'matched') {
      return [
        {
          ...item.next,
          x: interpolate(item.prev.x, item.next.x, animationElapsedTime),
          y: interpolate(item.prev.y, item.next.y, animationElapsedTime),
        },
      ];
    }
    // added: animate from center
    return [
      {
        ...item.next,
        x: interpolate(item.next.cx, item.next.x, animationElapsedTime),
        y: interpolate(item.next.cy, item.next.y, animationElapsedTime),
      },
    ];
  });
};

function PolygonWithAnimation({
  props,
  previousPointsRef,
  previousBaseLinePointsRef,
}: {
  props: InternalRadarProps;
  previousPointsRef: MutableRefObject<ReadonlyArray<RadarPoint> | undefined>;
  previousBaseLinePointsRef: MutableRefObject<ReadonlyArray<RadarPoint> | undefined>;
}) {
  const {
    points,
    baseLinePoints,
    isAnimationActive,
    animationBegin,
    animationDuration,
    animationEasing,
    animationMatchBy,
    animationInterpolateFn,
    onAnimationStart,
    onAnimationEnd,
  } = props;
  const baseLineAnimationState = useAnimationStartSnapshot(props, previousBaseLinePointsRef);
  const prevBaseLinePoints = baseLineAnimationState.startValue;
  const baseLineAnimationItems = matchAnimationItems(prevBaseLinePoints ?? null, baseLinePoints, animationMatchBy);

  const { isAnimating, handleAnimationStart, handleAnimationEnd } = useAnimationCallbacks(
    onAnimationStart,
    onAnimationEnd,
  );

  const layout = usePolarChartLayout();

  if (layout == null) return null;

  return (
    <RadarLabelListProvider showLabels={!isAnimating} points={points}>
      <AnimatedItems
        animationInput={props}
        animationIdPrefix="recharts-radar-"
        items={points}
        previousItemsRef={previousPointsRef}
        isAnimationActive={isAnimationActive}
        animationBegin={animationBegin}
        animationDuration={animationDuration}
        animationEasing={animationEasing}
        onAnimationStart={handleAnimationStart}
        onAnimationEnd={handleAnimationEnd}
        animationInterpolateFn={animationInterpolateFn}
        animationMatchBy={animationMatchBy}
        layout={layout}
      >
        {(stepData, animationElapsedTime) => {
          const stepBaseLinePoints =
            animationElapsedTime === 1
              ? baseLinePoints
              : animationInterpolateFn(baseLineAnimationItems, animationElapsedTime, layout);
          baseLineAnimationState.syncStepValue(stepBaseLinePoints, animationElapsedTime);
          return <StaticPolygon points={stepData} baseLinePoints={stepBaseLinePoints} props={props} />;
        }}
      </AnimatedItems>
      <LabelListFromLabelProp label={props.label} />
      {props.children}
    </RadarLabelListProvider>
  );
}

function RenderPolygon(props: InternalRadarProps) {
  const previousPointsRef = useRef<ReadonlyArray<RadarPoint> | undefined>(undefined);
  const previousBaseLinePointsRef = useRef<ReadonlyArray<RadarPoint> | undefined>(undefined);

  return (
    <PolygonWithAnimation
      props={props}
      previousPointsRef={previousPointsRef}
      previousBaseLinePointsRef={previousBaseLinePointsRef}
    />
  );
}

export const defaultRadarProps = {
  activeDot: true,
  angleAxisId: 0,
  animationBegin: 0,
  animationDuration: 1500,
  animationEasing: 'ease',
  animationMatchBy: matchByIndex,
  animationInterpolateFn: defaultRadarAnimateItems,
  dot: false,
  hide: false,
  isAnimationActive: 'auto',
  label: false,
  legendType: 'rect',
  radiusAxisId: 0,
  zIndex: DefaultZIndexes.area,
} as const satisfies Partial<Props>;

type PropsWithDefaults = RequiresDefaultProps<StringFillProps, typeof defaultRadarProps>;

/**
 * @public
 */
export type InternalRadarProps = RadarPropsWithDotFill & RadarComposedData;

function RadarWithState(props: InternalRadarProps) {
  const { hide, className, points } = props;

  if (hide) {
    return null;
  }

  const layerClass = clsx('recharts-radar', className);

  return (
    <ZIndexLayer zIndex={props.zIndex}>
      <Layer className={layerClass}>
        {props.fillObject != null && (
          <defs>
            <FillObjectDefinition id={getSeriesFillId(props.id)} fillObject={props.fillObject} color={props.fill} />
          </defs>
        )}
        <RenderPolygon {...props} />
      </Layer>
      <ActivePoints
        points={points}
        mainColor={getLegendItemColor(props.stroke, props.fill)}
        itemDataKey={props.dataKey}
        activeDot={props.activeDot}
        themedActiveStyles={props.themedActiveStyles}
      />
    </ZIndexLayer>
  );
}

function RadarImpl(props: RadarPropsWithDotFill) {
  const isPanorama = useIsPanorama();
  const radarPoints = useAppSelector(state =>
    selectRadarPoints(state, props.radiusAxisId, props.angleAxisId, isPanorama, props.id),
  );

  if (radarPoints?.points == null) {
    return null;
  }

  return (
    <RadarWithState
      {...props}
      points={radarPoints?.points}
      baseLinePoints={radarPoints?.baseLinePoints}
      isRange={radarPoints?.isRange}
    />
  );
}

/**
 * @consumes PolarChartContext
 * @provides LabelListContext
 * @public
 */
export function Radar<DataPointType = any, DataValueType = any>(
  propsWithFillObject: Props<DataPointType, DataValueType>,
) {
  const { color: fillColor, fillObject } = splitFill(propsWithFillObject.fill);
  // From here on, `fill` is the base color
  const outsideProps: StringFillProps = { ...propsWithFillObject, fill: fillColor };
  const rechartsTheme = useRechartsTheme();
  const dataKey = useEffectiveDataKey({
    dataKey: outsideProps.dataKey,
    angleAxisId: outsideProps.angleAxisId ?? defaultRadarProps.angleAxisId,
    radiusAxisId: outsideProps.radiusAxisId ?? defaultRadarProps.radiusAxisId,
  });
  const graphicalItemThemeSelector = useGraphicalItemIdentity(dataKey, outsideProps);
  const themeFillObject = useGraphicalItemThemeFill(dataKey, outsideProps);
  const effectiveFillObject = fillObject ?? themeFillObject;
  const resolveLabelTheme = useSeriesLabelThemeResolver(graphicalItemThemeSelector);
  const graphicalItemTheme = useBackwardsCompatibleTheme<Omit<ColorGraphicalItemStyle, 'label'>>(
    graphicalItemThemeSelector,
    outsideProps,
    undefined,
  );
  const themeStrokeDasharray = graphicalItemTheme?.strokeDasharray;
  const unthemedColors = useUnthemedColors(outsideProps);
  const themedActiveStyles = useThemedActiveStyles(graphicalItemThemeSelector, outsideProps);
  const propsWithTheme: StringFillProps = {
    ...outsideProps,
    dataKey,
    activeDot: outsideProps.activeDot,
    // the legend shows the same symbol as the dots, unless legendType says otherwise
    legendType: outsideProps.legendType ?? getDotSymbol(outsideProps.dot),
    fill: outsideProps.fill ?? graphicalItemTheme?.fill,
    fillOpacity: outsideProps.fillOpacity ?? graphicalItemTheme?.fillOpacity,
    stroke: outsideProps.stroke ?? graphicalItemTheme?.stroke,
    strokeOpacity: outsideProps.strokeOpacity ?? graphicalItemTheme?.strokeOpacity,
    strokeWidth: outsideProps.strokeWidth ?? graphicalItemTheme?.strokeWidth,
    strokeDasharray:
      outsideProps.strokeDasharray ??
      (Array.isArray(themeStrokeDasharray) ? themeStrokeDasharray.join(',') : themeStrokeDasharray),
  };
  const props: PropsWithDefaults = resolveDefaultProps(propsWithTheme, defaultRadarProps);
  const dotFill =
    outsideProps.fill ??
    (rechartsTheme == null ? props.fill : getLegendItemColor(props.stroke, graphicalItemTheme?.fill));
  const labelColors = useSeriesDataLabelColors(getLegendItemColor(props.stroke, props.fill));
  return (
    <RegisterGraphicalItemId id={props.id} type="radar">
      {id => (
        <>
          <SetPolarGraphicalItem
            type="radar"
            id={id}
            data={undefined} // Radar does not have data prop, why?
            dataKey={props.dataKey}
            hide={props.hide}
            angleAxisId={props.angleAxisId}
            radiusAxisId={props.radiusAxisId}
          />
          <SetPolarLegendPayload
            legendPayload={computeLegendPayloadFromRadarSectors(props, dotFill, effectiveFillObject)}
          />
          <SetRadarTooltipEntrySettings
            dataKey={props.dataKey}
            stroke={props.stroke}
            strokeWidth={props.strokeWidth}
            fill={props.fill}
            name={props.name}
            hide={props.hide}
            tooltipType={props.tooltipType}
            id={id}
          />
          <DataLabelThemeContextProvider value={resolveLabelTheme}>
            <DataLabelColorsContextProvider value={labelColors}>
              <RadarImpl
                {...props}
                id={id}
                dotFill={dotFill}
                fillObject={effectiveFillObject}
                unthemedColors={unthemedColors}
                themedActiveStyles={themedActiveStyles}
              />
            </DataLabelColorsContextProvider>
          </DataLabelThemeContextProvider>
        </>
      )}
    </RegisterGraphicalItemId>
  );
}

Radar.displayName = 'Radar';
