const interpolationGenerator = (a: number, b: number) => {
  const ka = +a;
  const kb = b - ka;
  return (animationElapsedTime: number) => ka + kb * animationElapsedTime;
};

const centerY = (node: SankeyNode) => node.y + node.dy / 2;

const cubicValue = (start: number, control1: number, control2: number, end: number, t: number): number => {
  const inverseT = 1 - t;
  return inverseT ** 3 * start + 3 * inverseT ** 2 * t * control1 + 3 * inverseT * t ** 2 * control2 + t ** 3 * end;
};

// TODO why is this not reading dataKey?
const getValue = (entry: LinkDataItem | SankeyNode | undefined): number => (entry && entry.value) || 0;

const getSumOfIds = (links: ReadonlyArray<LinkDataItem>, ids: number[]): number =>
  ids.reduce((result, id) => result + getValue(links[id]), 0);

const getSumWithWeightedSource = (
  tree: ReadonlyArray<SankeyNode>,
  links: ReadonlyArray<LinkDataItemDy>,
  ids: number[],
) =>
  ids.reduce((result, id) => {
    const link = links[id];
    if (link == null) {
      return result;
    }
    const sourceNode = tree[link.source];
    if (sourceNode == null) {
      return result;
    }

    return result + centerY(sourceNode) * getValue(links[id]);
  }, 0);

const getSumWithWeightedTarget = (
  tree: ReadonlyArray<SankeyNode>,
  links: ReadonlyArray<LinkDataItemDy>,
  ids: ReadonlyArray<number>,
): number =>
  ids.reduce((result: number, id: number) => {
    const link = links[id];
    if (link == null) {
      return result;
    }
    const targetNode = tree[link.target];
    if (targetNode == null) {
      return result;
    }

    return result + centerY(targetNode) * getValue(links[id]);
  }, 0);

const ascendingY = (a: { y: number }, b: { y: number }) => a.y - b.y;

type NodeAdjacency = {
  sourceNodes: number[];
  sourceLinks: number[];
  targetNodes: number[];
  targetLinks: number[];
};

/**
 * For every node, finds the links that point to it and the links that leave it, in one pass over the links.
 * The indexes in each list are in the same order as the links. Links with a missing or out of range end are skipped.
 *
 * @param links all links
 * @param nodeCount number of nodes
 * @returns adjacency of each node, by node index
 */
const getAdjacencyOfNodes = (links: ReadonlyArray<LinkDataItem>, nodeCount: number): NodeAdjacency[] => {
  const result: NodeAdjacency[] = [];
  for (let id = 0; id < nodeCount; id++) {
    result.push({ sourceNodes: [], sourceLinks: [], targetNodes: [], targetLinks: [] });
  }
  const isNodeIndex = (value: unknown): value is number =>
    typeof value === 'number' && Number.isInteger(value) && value >= 0 && value < nodeCount;

  for (let i = 0, len = links.length; i < len; i++) {
    const link = links[i];
    if (link == null) {
      continue;
    }
    const { source, target } = link;
    /*
     * A link with one end outside the nodes is skipped on both ends. Recording the valid end alone
     * would give that node a phantom source, so it would no longer count as a root of the layout.
     */
    if (!isNodeIndex(source) || !isNodeIndex(target)) {
      continue;
    }

    const sourceAdjacency = result[source];
    sourceAdjacency?.targetNodes.push(target);
    sourceAdjacency?.targetLinks.push(i);

    const targetAdjacency = result[target];
    targetAdjacency?.sourceNodes.push(source);
    targetAdjacency?.sourceLinks.push(i);
  }

  return result;
};

const updateDepthOfTargets = (tree: SankeyNode[], curNode: SankeyNode, onPath: Set<SankeyNode> = new Set()): void => {
  const { targetNodes } = curNode;

  /*
   * `onPath` holds the nodes on the current recursion path, so a link that points back to one of them
   * is skipped instead of followed. Depth is the longest path to a node, so it grows on every trip
   * around a cycle and the `newDepth > target.depth` guard below stays true forever: without this the
   * recursion has no fixed point and exhausts the call stack.
   *
   * This tracks the current path and not every node already seen, because a node in a directed acyclic
   * graph is legitimately reached again by a longer route, and that is the route whose depth wins.
   */
  onPath.add(curNode);

  for (let i = 0, len = targetNodes.length; i < len; i++) {
    const targetNode = targetNodes[i];
    if (targetNode == null) {
      continue;
    }
    const target = tree[targetNode];

    if (target && !onPath.has(target)) {
      const newDepth = curNode.depth + 1;
      /*
       * Only recurse when the depth grows. Depth is the longest path to a node, so once it stops increasing
       * the subtree is already up to date; without this guard every path through the graph is walked
       * separately, which explodes combinatorially on dense graphs.
       */
      if (newDepth > target.depth) {
        target.depth = newDepth;
        updateDepthOfTargets(tree, target, onPath);
      }
    }
  }

  onPath.delete(curNode);
};

const getNodesTree = (
  { nodes, links }: SankeyData,
  width: number,
  nodeWidth: number,
  align: 'left' | 'justify',
): { tree: SankeyNode[]; maxDepth: number } => {
  const adjacencyOfNodes = getAdjacencyOfNodes(links, nodes.length);
  const tree = nodes.map((entry: SankeyNode, index: number) => {
    const result = adjacencyOfNodes[index] ?? { sourceNodes: [], sourceLinks: [], targetNodes: [], targetLinks: [] };

    return {
      ...entry,
      ...result,
      value: Math.max(getSumOfIds(links, result.sourceLinks), getSumOfIds(links, result.targetLinks)),
      depth: 0,
    };
  });

  for (let i = 0, len = tree.length; i < len; i++) {
    const node = tree[i];

    if (node != null && !node.sourceNodes.length) {
      updateDepthOfTargets(tree, node);
    }
  }
  const maxDepth = maxBy(tree, (entry: SankeyNode) => entry.depth)?.depth ?? 0;

  if (maxDepth >= 1) {
    const childWidth = (width - nodeWidth) / maxDepth;
    for (let i = 0, len = tree.length; i < len; i++) {
      const node = tree[i];
      if (node == null) {
        continue;
      }

      if (!node.targetNodes.length) {
        if (align === 'justify') {
          node.depth = maxDepth;
        }
      }
      node.x = node.depth * childWidth;
      node.dx = nodeWidth;
    }
  }

  return { tree, maxDepth };
};

const getDepthTree = (tree: SankeyNode[]): SankeyNode[][] => {
  const result: SankeyNode[][] = [];

  for (let i = 0, len = tree.length; i < len; i++) {
    const node = tree[i];
    if (node == null) {
      continue;
    }

    if (!result[node.depth]) {
      result[node.depth] = [];
    }

    result[node.depth]?.push(node);
  }

  return result;
};

type LinkDataItemDy = LinkDataItem & { dy: number; sy?: number; ty?: number };

/**
 * @public
 */
export type SankeyVerticalAlign = 'justify' | 'top';

const updateYOfTree = (
  depthTree: SankeyNode[][],
  height: number,
  nodePadding: number,
  links: LinkDataItem[],
  verticalAlign: SankeyVerticalAlign,
): Array<LinkDataItemDy> => {
  let yRatio: number = Math.min(
    ...depthTree.map(nodes => {
      const value = sumBy(nodes, getValue);
      return value === 0 ? Infinity : (height - (nodes.length - 1) * nodePadding) / value;
    }),
  );
  if (yRatio === Infinity) {
    yRatio = 0;
  }

  for (let d = 0, maxDepth = depthTree.length; d < maxDepth; d++) {
    const nodes = depthTree[d];
    if (nodes == null) {
      continue;
    }

    if (verticalAlign === 'top') {
      let currentY = 0;
      for (let i = 0, len = nodes.length; i < len; i++) {
        const node = nodes[i];
        if (node == null) {
          continue;
        }

        node.dy = node.value * yRatio;
        node.y = currentY;
        currentY += node.dy + nodePadding;
      }
    } else {
      for (let i = 0, len = nodes.length; i < len; i++) {
        const node = nodes[i];
        if (node == null) {
          continue;
        }

        node.y = i;
        node.dy = node.value * yRatio;
      }
    }
  }

  return links.map((link: LinkDataItem): LinkDataItemDy => ({ ...link, dy: getValue(link) * yRatio }));
};

const resolveCollisions = (depthTree: SankeyNode[][], height: number, nodePadding: number, sort = true) => {
  for (let i = 0, len = depthTree.length; i < len; i++) {
    const nodes = depthTree[i];
    if (nodes == null) {
      continue;
    }
    const n = nodes.length;

    // Sort by the value of y
    if (sort) {
      nodes.sort(ascendingY);
    }

    let y0 = 0;
    for (let j = 0; j < n; j++) {
      const node = nodes[j];
      if (node == null) {
        continue;
      }
      const dy = y0 - node.y;

      if (dy > 0) {
        node.y += dy;
      }

      y0 = node.y + node.dy + nodePadding;
    }

    y0 = height + nodePadding;
    for (let j = n - 1; j >= 0; j--) {
      const node = nodes[j];
      if (node == null) {
        continue;
      }
      const dy = node.y + node.dy + nodePadding - y0;

      if (dy > 0) {
        node.y -= dy;
        y0 = node.y;
      } else {
        break;
      }
    }
  }
};

const relaxLeftToRight = (
  tree: ReadonlyArray<SankeyNode>,
  depthTree: SankeyNode[][],
  links: ReadonlyArray<LinkDataItemDy>,
  alpha: number,
) => {
  for (let i = 0, maxDepth = depthTree.length; i < maxDepth; i++) {
    const nodes = depthTree[i];
    if (nodes == null) {
      continue;
    }

    for (let j = 0, len = nodes.length; j < len; j++) {
      const node = nodes[j];
      if (node == null) {
        continue;
      }

      if (node.sourceLinks.length) {
        const sourceSum = getSumOfIds(links, node.sourceLinks);
        const weightedSum = getSumWithWeightedSource(tree, links, node.sourceLinks);
        const y = sourceSum === 0 ? centerY(node) : weightedSum / sourceSum;

        node.y += (y - centerY(node)) * alpha;
      }
    }
  }
};

const relaxRightToLeft = (
  tree: ReadonlyArray<SankeyNode>,
  /*
   * depthTree array is modified by this method!
   */
  depthTree: SankeyNode[][],
  links: ReadonlyArray<LinkDataItemDy>,
  alpha: number,
) => {
  for (let i = depthTree.length - 1; i >= 0; i--) {
    const nodes = depthTree[i];
    if (nodes == null) {
      continue;
    }

    for (let j = 0, len = nodes.length; j < len; j++) {
      const node = nodes[j];
      if (node == null) {
        continue;
      }

      if (node.targetLinks.length) {
        const targetSum = getSumOfIds(links, node.targetLinks);
        const weightedSum = getSumWithWeightedTarget(tree, links, node.targetLinks);
        const y = targetSum === 0 ? centerY(node) : weightedSum / targetSum;

        node.y += (y - centerY(node)) * alpha;
      }
    }
  }
};

const updateYOfLinks = (tree: SankeyNode[], links: LinkDataItemDy[]): void => {
  for (let i = 0, len = tree.length; i < len; i++) {
    const node = tree[i];
    if (node == null) {
      continue;
    }
    let sy = 0;
    let ty = 0;

    node.targetLinks.sort((a, b) => {
      const targetA = links[a]?.target;
      const targetB = links[b]?.target;
      if (targetA == null || targetB == null) {
        return 0;
      }
      const yA = tree[targetA]?.y;
      const yB = tree[targetB]?.y;
      if (yA == null || yB == null) {
        return 0;
      }
      return yA - yB;
    });
    node.sourceLinks.sort((a, b) => {
      const sourceA = links[a]?.source;
      const sourceB = links[b]?.source;
      if (sourceA == null || sourceB == null) {
        return 0;
      }
      const yA = tree[sourceA]?.y;
      const yB = tree[sourceB]?.y;
      if (yA == null || yB == null) {
        return 0;
      }
      return yA - yB;
    });

    for (let j = 0, tLen = node.targetLinks.length; j < tLen; j++) {
      const targetLink = node.targetLinks[j];
      if (targetLink == null) {
        continue;
      }
      const link = links[targetLink];

      if (link) {
        link.sy = sy;
        sy += link.dy;
      }
    }

    for (let j = 0, sLen = node.sourceLinks.length; j < sLen; j++) {
      const sourceLink = node.sourceLinks[j];
      if (sourceLink == null) {
        continue;
      }
      const link = links[sourceLink];

      if (link) {
        link.ty = ty;
        ty += link.dy;
      }
    }
  }
};

const getLinkYAtX = (sourceNode: SankeyNode, targetNode: SankeyNode, link: LinkDataItemDy, x: number): number => {
  const sourceX = sourceNode.x + sourceNode.dx;
  const targetX = targetNode.x;
  const progress = targetX === sourceX ? 0 : (x - sourceX) / (targetX - sourceX);
  const boundedProgress = Math.min(Math.max(progress, 0), 1);
  const sourceY = sourceNode.y + (link.sy ?? 0) + link.dy / 2;
  const targetY = targetNode.y + (link.ty ?? 0) + link.dy / 2;

  return cubicValue(sourceY, sourceY, targetY, targetY, boundedProgress);
};

const resolveNodeLinkCollisions = (
  tree: SankeyNode[],
  depthTree: SankeyNode[][],
  links: LinkDataItemDy[],
  height: number,
  nodePadding: number,
) => {
  const depthByNode = new Map<SankeyNode, number>();

  for (let depth = 0; depth < depthTree.length; depth++) {
    const nodes = depthTree[depth];
    if (nodes == null) {
      continue;
    }

    for (const node of nodes) {
      depthByNode.set(node, depth);
    }
  }

  for (let depth = 0; depth < depthTree.length; depth++) {
    const nodes = depthTree[depth];
    if (nodes == null || nodes.length === 0) {
      continue;
    }

    const depthX = nodes[0] == null ? undefined : nodes[0].x + nodes[0].dx / 2;
    if (depthX == null) {
      continue;
    }

    const fixedObstacles = links.flatMap(link => {
      const sourceNode = tree[link.source];
      const targetNode = tree[link.target];
      if (sourceNode == null || targetNode == null) {
        return [];
      }

      const sourceDepth = depthByNode.get(sourceNode);
      const targetDepth = depthByNode.get(targetNode);
      if (sourceDepth == null || targetDepth == null) {
        return [];
      }

      if (depth <= Math.min(sourceDepth, targetDepth) || depth >= Math.max(sourceDepth, targetDepth)) {
        return [];
      }

      const y = getLinkYAtX(sourceNode, targetNode, link, depthX) - link.dy / 2;
      return [{ y, dy: link.dy, fixed: true as const }];
    });

    const containedNodeObstacles = fixedObstacles.filter(obstacle =>
      nodes.some(node => node.y >= obstacle.y && node.y + node.dy <= obstacle.y + obstacle.dy),
    );

    if (containedNodeObstacles.length === 0) {
      continue;
    }

    type CollisionItem = { node: SankeyNode; fixed: false } | { y: number; dy: number; fixed: true };
    const getItemY = (item: CollisionItem): number => (item.fixed ? item.y : item.node.y);
    const getItemHeight = (item: CollisionItem): number => (item.fixed ? item.dy : item.node.dy);
    let items: CollisionItem[] = [
      ...nodes.map(node => ({ node, fixed: false as const })),
      ...containedNodeObstacles,
    ].sort((a, b) => getItemY(a) - getItemY(b));

    let nextY = 0;
    for (const item of items) {
      if (item.fixed) {
        nextY = Math.max(nextY, item.y + item.dy + nodePadding);
        continue;
      }

      if (item.node.y < nextY) {
        item.node.y = nextY;
      }
      nextY = item.node.y + item.node.dy + nodePadding;
    }

    items = items.sort((a, b) => getItemY(a) - getItemY(b));

    let previousY = height + nodePadding;
    for (let i = items.length - 1; i >= 0; i--) {
      const item = items[i];
      if (item == null) {
        continue;
      }

      if (item.fixed) {
        previousY = Math.min(previousY, item.y - nodePadding);
        continue;
      }

      // This backward pass only keeps moved nodes within the chart bounds.
      // It intentionally does not iterate again against fixed obstacles above,
      // because this fix is scoped to the fully-contained skipped-depth case.
      const dy = item.node.y + getItemHeight(item) + nodePadding - previousY;
      if (dy > 0) {
        item.node.y -= dy;
      }
      previousY = item.node.y;
    }
  }
};

export const computeData = ({
  data,
  width,
  height,
  iterations,
  nodeWidth,
  nodePadding,
  sort,
  verticalAlign,
  align,
}: {
  data: SankeyData;
  width: number;
  height: number;
  iterations: number;
  nodeWidth: number;
  nodePadding: number;
  sort: boolean;
  verticalAlign: SankeyVerticalAlign;
  align: 'left' | 'justify';
}): {
  nodes: ReadonlyArray<SankeyNode>;
  links: ReadonlyArray<SankeyLink>;
} => {
  const { links } = data;
  const { tree } = getNodesTree(data, width, nodeWidth, align);
  const depthTree = getDepthTree(tree);
  const linksWithDy: Array<LinkDataItemDy> = updateYOfTree(depthTree, height, nodePadding, links, verticalAlign);

  resolveCollisions(depthTree, height, nodePadding, sort);

  if (verticalAlign === 'justify') {
    let alpha = 1;
    for (let i = 1; i <= iterations; i++) {
      relaxRightToLeft(tree, depthTree, linksWithDy, (alpha *= 0.99));

      resolveCollisions(depthTree, height, nodePadding, sort);

      relaxLeftToRight(tree, depthTree, linksWithDy, alpha);

      resolveCollisions(depthTree, height, nodePadding, sort);
    }
  }

  updateYOfLinks(tree, linksWithDy);
  resolveNodeLinkCollisions(tree, depthTree, linksWithDy, height, nodePadding);
  updateYOfLinks(tree, linksWithDy);

  // @ts-expect-error updateYOfLinks modifies the links array to add sy and ty in place
  const newLinks: ReadonlyArray<SankeyLink> = linksWithDy;

  return { nodes: tree, links: newLinks };
};

const getNodeCoordinateOfTooltip = (item: NodeProps) => {
  return { x: +item.x + +item.width / 2, y: +item.y + +item.height / 2 };
};

const getLinkCoordinateOfTooltip = (item: LinkProps): Coordinate | undefined => {
  return 'sourceX' in item
    ? {
        x: (item.sourceX + item.targetX) / 2,
        y: (item.sourceY + item.targetY) / 2,
      }
    : undefined;
};

type SankeyTooltipPayload = { payload: SankeyNode | SankeyLink; name: unknown; value: unknown; color?: string };

/**
 * Returns true if the value is a color that paints something, as opposed to a missing color or `none`.
 * @param value fill or stroke
 */
function isPaint(value: unknown): value is string {
  return typeof value === 'string' && value !== 'none';
}

type PaintedProps = { fill?: unknown; stroke?: unknown; style?: unknown };

/**
 * Returns the color that a node or link is actually painted with.
 * Inline `style` wins over the presentation attribute, same as in the browser.
 * @param props resolved props of a node or link
 * @param key which paint to read
 * @returns the color, or undefined if the shape is not painted with a color
 */
function getRenderedPaint(props: PaintedProps | undefined, key: 'fill' | 'stroke'): string | undefined {
  if (props == null) {
    return undefined;
  }
  const { style } = props;
  const fromStyle: unknown = style != null && typeof style === 'object' ? Reflect.get(style, key) : undefined;
  if (fromStyle != null) {
    return isPaint(fromStyle) ? fromStyle : undefined;
  }
  const fromAttribute = props[key];
  return isPaint(fromAttribute) ? fromAttribute : undefined;
}

const getPayloadOfTooltip = (
  item: { payload: SankeyNode | SankeyLink } & PaintedProps,
  type: SankeyElementType,
  nameKey: DataKey<SankeyLink | SankeyNode, string> | undefined,
): SankeyTooltipPayload | undefined => {
  const { payload } = item;
  if (type === 'node') {
    return {
      payload,
      name: getValueByDataKey(payload, nameKey, ''),
      value: getValueByDataKey(payload, 'value'),
      color: getRenderedPaint(item, 'fill'),
    };
  }
  if ('source' in payload && payload.source && payload.target) {
    // @ts-expect-error we're sending number indexes as source and target, but getValueByDataKey expects objects
    const sourceName = getValueByDataKey(payload.source, nameKey, '');
    // @ts-expect-error we're sending number indexes as source and target, but getValueByDataKey expects objects
    const targetName = getValueByDataKey(payload.target, nameKey, '');

    return {
      payload,
      name: `${sourceName} - ${targetName}`,
      value: getValueByDataKey(payload, 'value'),
      color: getRenderedPaint(item, 'stroke'),
    };
  }

  return undefined;
};

export const sankeyPayloadSearcher: TooltipPayloadSearcher = (
  _: unknown,
  activeIndex: TooltipIndex,
  computedData?: unknown,
  nameKey?,
): SankeyTooltipPayload | undefined => {
  if (activeIndex == null || typeof activeIndex !== 'string') {
    return undefined;
  }
  if (computedData == null || typeof computedData !== 'object') {
    return undefined;
  }
  const splitIndex = activeIndex.split('-');
  const [targetType, index] = splitIndex;
  const item = get(computedData, `${targetType}s[${index}]`);
  if (item) {
    // @ts-expect-error nameKey type does not match SankeyElementType
    const payload = getPayloadOfTooltip(item, targetType as SankeyElementType, nameKey);
    return payload;
  }
  return undefined;
};

const options: ChartOptions = {
  chartName: 'Sankey',
  defaultTooltipEventType: 'item',
  validateTooltipEventTypes: ['item'],
  tooltipPayloadSearcher: sankeyPayloadSearcher,
  eventEmitter: undefined,
};

