/**
 * @public
 */
export interface ScatterPointNode {
  x?: number | string;
  y?: number | string;
  z?: number | string;
}

/**
 * Scatter coordinates are nullable because sometimes the point value is out of the domain,
 * and we can't compute a valid coordinate for it.
 *
 * Scatter -> Symbol ignores points with null cx or cy so those won't render if using the default shapes.
 * However: the points are exposed via various props and can be used in custom shapes so we keep them around.
 * @public
 */
export interface ScatterPointItem {
  /**
   * The x coordinate of the point center in pixels.
   */
  cx: number | undefined;
  /**
   * The y coordinate of the point center in pixels.
   */
  cy: number | undefined;
  /**
   * The x coordinate (in pixels) of the top-left corner of the rectangle that wraps the point.
   */
  x: number | undefined;
  /**
   * The y coordinate (in pixels) of the top-left corner of the rectangle that wraps the point.
   */
  y: number | undefined;
  /**
   * ScatterPointItem size is an abstract number that is used to calculate the radius of the point.
   * It's not the radius itself, but rather a value that is used to calculate the radius.
   * Interacts with the zAxis range.
   */
  size: number;
  /**
   * Width of the point in pixels.
   */
  width: number;
  /**
   * Height of the point in pixels.
   */
  height: number;
  node: ScatterPointNode;
  payload?: any;
  tooltipPayload?: TooltipPayload;
  tooltipPosition: Coordinate;
}

/**
 * @public
 */
export type ScatterCustomizedShape = ActiveShape<ScatterShapeProps & InnerSymbolsProp, SVGPathElement> | SymbolType;

/**
 * Internal props, combination of external props + defaultProps + private Recharts state
 */
interface ScatterInternalProps extends ZIndexable {
  /**
   * The base color of the points.
   */
  fill?: string;
  /**
   * The fill object of the Scatter, from props or from the theme. Points without their own fill paint with it.
   */
  fillObject?: RechartsFill;
  data?: ChartData;
  xAxisId: string | number;
  yAxisId: string | number;
  zAxisId: string | number;

  dataKey?: DataKey<any>;

  line?: ReactElement<SVGElement> | ((props: any) => ReactElement<SVGElement>) | CurveProps | boolean;
  lineType: 'fitting' | 'joint';
  lineJointType: CurveType;
  legendType: LegendType;
  tooltipType?: TooltipType;
  formatter?: Formatter;
  className?: string;
  name?: string;

  activeShape?: ScatterCustomizedShape;
  shape: ScatterCustomizedShape;
  points: ReadonlyArray<ScatterPointItem>;
  hide: boolean;
  label?: ImplicitLabelListType;
  /**
   * Explicit style props without theme contributions.
   * Applied to data entries that define their own colors, so that they ignore the theme colors.
   * Undefined when there is no active theme.
   */
  unthemedColors?: UnthemedColors;
  /**
   * Theme styles of the active shape, without the ones that explicit props override.
   * Undefined when there is no active theme, or when the theme has no active styles.
   */
  themedActiveStyles?: ColorStyles2D;

  isAnimationActive: boolean | 'auto';
  animationBegin: number;
  animationDuration: AnimationDuration;
  animationEasing: EasingInput;
  animationInterpolateFn: AnimationInterpolateFn<ScatterPointItem, CartesianLayout>;
  animationMatchBy: AnimationMatchByProp<ScatterPointItem>;

  needClip: boolean;

  id: GraphicalItemId;
  children?: ReactNode;
}

/**
 * External props, intended for end users to fill in
 *
 * The type is exported only so that TypeScript can name it in the declaration files of projects
 * that wrap Recharts components. It is not part of the public API and may change in any release.
 *
 * @internal
 */
export interface ScatterProps<DataPointType = any, DataValueType = any>
  extends DataProvider<DataPointType>, ValueAxisDataConsumer<DataPointType, DataValueType>, ZIndexable {
  /**
   * The fill of the points. Either a color string, or a {@link RechartsFill} object with an SVG definition,
   * such as a pattern or a gradient.
   *
   * With a fill object, Recharts renders the definition with a unique ID, in the chart and in the Legend icon.
   * Tooltip and labels use the solid `color` of the fill object.
   * If the fill object has no `color`, the points keep the theme colors and the definition gets the theme color.
   * Data entries with their own `fill` keep it.
   *
   * @example <Scatter fill={{ definition: linearGradient(gradients.fadeDown) }} />
   */
  fill?: string | RechartsFill;
  /**
   * Unique identifier of this component.
   * Used as an HTML attribute `id`, and also to identify this element internally.
   *
   * If undefined, Recharts will generate a unique ID automatically.
   */
  id?: string;
  /**
   * The id of XAxis which is corresponding to the data. Required when there are multiple XAxes.
   * @defaultValue 0
   */
  xAxisId?: AxisId;
  /**
   * The id of YAxis which is corresponding to the data. Required when there are multiple YAxes.
   * @defaultValue 0
   */
  yAxisId?: AxisId;
  /**
   * The id of ZAxis which is corresponding to the data. Required when there are multiple ZAxes.
   *
   * ZAxis does not render directly, has no ticks and no tick line.
   * It is used to control the size of each scatter point.
   *
   * @defaultValue 0
   * @see {@link https://recharts.github.io/en-US/examples/ThreeDimScatterChart/ Scatter chart with Z axis}
   */
  zAxisId?: AxisId;

  /**
   * Renders line connecting individual points.
   * Options:
   * - `false`: no line is drawn.
   * - `true`: a default line is drawn.
   * - `ReactElement`: the option is the custom line element.
   * - `function`: the function will be called to render customized line.
   * - `object`: the option is the props of Curve element.
   *
   * Also see the `lineType` prop which controls how is this line calculated.
   *
   * @defaultValue false
   * @example <Scatter line />
   * @example <Scatter line={CustomizedLineComponent} />
   * @example <Scatter line={{ strokeDasharray: '5 5' }} />
   *
   * @see {@link https://recharts.github.io/en-US/examples/JointLineScatterChart/ Scatter chart with joint line}
   */
  line?: ReactElement<SVGElement> | ((props: any) => ReactElement<SVGElement>) | CurveProps | boolean;
  /**
   * Determines calculation method of the line if the `line` prop is set.
   * Options:
   * - `'joint'`: line will be generated by connecting all the points.
   * - `'fitting'`: line will be generated by fitting algorithm (linear regression).
   *
   * Has no effect if `line` prop is not set or is false.
   *
   * @defaultValue joint
   * @example <Scatter line lineType="fitting" />
   * @see {@link https://recharts.github.io/en-US/examples/JointLineScatterChart/ Scatter chart with joint line}
   */
  lineType?: 'fitting' | 'joint';
  /**
   * Determines the shape of joint line.
   * Same as `type` prop on Curve, Line and Area components.
   *
   * Has no effect if `line` prop is not set or is false or if `lineType` is 'fitting'.
   *
   * @defaultValue linear
   * @see {@link https://recharts.github.io/en-US/examples/JointLineScatterChart/ Scatter chart with joint line}
   */
  lineJointType?: CurveType;
  /**
   * The type of icon in legend.
   * If set to 'none', no legend item will be rendered.
   *
   * By default, the legend icon shows the same predefined symbol as the data points, if they use one.
   *
   * @defaultValue 'circle'
   * @example <Scatter legendType="diamond" />
   */
  legendType?: LegendType;
  tooltipType?: TooltipType;
  /**
   * Formats the value displayed in the tooltip for this Scatter.
   * When set, takes precedence over the `formatter` prop on the Tooltip component.
   */
  formatter?: Formatter;
  className?: string;
  /**
   * The name of data.
   * This option will be used in tooltip and legend to represent this graphical item.
   * If no value was set to this option, the value of dataKey will be used alternatively.
   */
  name?: string;

  /**
   * This component is rendered when this graphical item is activated
   * (could be by mouse hover, touch, keyboard, programmatically).
   *
   * @see {@link https://recharts.github.io/en-US/examples/SimpleScatterChart/ Scatter chart with custom active shape}
   * @example <Scatter activeShape={{ fill: 'red' }} />
   */
  activeShape?: ScatterCustomizedShape;
  /**
   * Determines the shape of individual data points.
   * - Can be one of the predefined shapes as a string, which will be passed to {@link Symbols} component.
   * - If set a ReactElement, the shape of point can be customized.
   * - If set a function, the function will be called to render customized shape.
   * - During animations, the function shape also receives `animationElapsedTime`, `isAnimating`, and `isEntrance`.
   * @defaultValue circle
   *
   * @example <Scatter shape={CustomizedShapeComponent} />
   * @example <Scatter shape="diamond" />
   *
   * @see {@link https://recharts.github.io/en-US/examples/JointLineScatterChart/ Scatter chart with custom shapes}
   */
  shape?: ScatterCustomizedShape;
  /**
   * Hides the whole graphical element when true.
   *
   * Hiding an element is different from removing it from the chart:
   * Hidden graphical elements are still visible in Legend,
   * and can be included in axis domain calculations,
   * depending on `includeHidden` props of your XAxis/YAxis.
   *
   * @defaultValue false
   */
  hide?: boolean;
  /**
   * Renders one label for each data point. Options:
   * - `true`: renders default labels;
   * - `false`: no labels are rendered;
   * - `object`: the props of LabelList component;
   * - `ReactElement`: a custom SVG label element, such as `<text>` or `<g>`.
   *   HTML elements such as `<div>` are not valid inside the chart SVG and may trigger React DOM warnings.
   * - `function`: a render function of custom label.
   *
   * @defaultValue false
   */
  label?: ImplicitLabelListType;

  /**
   * If set false, animation of Scatter points will be disabled.
   * If set "auto", the animation will be disabled in SSR and will respect the user's prefers-reduced-motion system preference for accessibility.
   * @defaultValue 'auto'
   */
  isAnimationActive?: boolean | 'auto';
  /**
   * Specifies when the animation should begin, the unit of this option is ms.
   * @defaultValue 0
   */
  animationBegin?: number;
  /**
   * Specifies the duration of animation, the unit of this option is ms.
   * @defaultValue 400
   */
  animationDuration?: AnimationDuration;
  /**
   * The type of easing function.
   * @defaultValue 'linear'
   */
  animationEasing?: EasingInput;
  /**
   * Custom animation function for interpolating data items.
   * When provided, this replaces the default animation interpolation.
   *
   * @param prevItems The items from the previous animation frame, or null on first render
   * @param nextItems The target items to animate towards
   * @param animationElapsedTime A normalized time value (0 = start, 1 = end)
   * @returns The interpolated items at time animationElapsedTime
   *
   * @since 3.9
   * @see {@link https://recharts.github.io/en-US/guide/animations/ Animations guide}
   */
  animationInterpolateFn?: AnimationInterpolateFn<ScatterPointItem, CartesianLayout>;
  /**
   * Strategy for matching previous items to next items during animation.
   * Determines how Recharts pairs old data points with new data points
   * to create smooth transitions.
   *
   * - `matchAppend` (default): match sequentially by index and treat newly appended items as new
   * - `matchByIndex`: match by array position with proportional stretching
   * - `matchByDataKey('someKey')`: match by a data key from the payload
   * - Custom function `(item, index) => key`: match by the returned key
   *
   * @defaultValue append
   * @see matchByIndex
   * @see matchByDataKey
   * @see matchAppend
   *
   * @since 3.9
   * @see {@link https://recharts.github.io/en-US/guide/animations/ Animations guide}
   */
  animationMatchBy?: AnimationMatchByProp<ScatterPointItem>;
  /**
   * Z-Index of this component and its children. The higher the value,
   * the more on top it will be rendered.
   * Components with higher zIndex will appear in front of components with lower zIndex.
   * If undefined or 0, the content is rendered in the default layer without portals.
   *
   * @since 3.4
   * @defaultValue 600
   * @see {@link https://recharts.github.io/en-US/guide/zIndex/ Z-Index and layers guide}
   */
  zIndex?: number;
  children?: ReactNode;
}

/**
 * Because of naming conflict, we are forced to ignore certain (valid) SVG attributes.
 */
type BaseScatterSvgProps = Omit<
  PresentationAttributesAdaptChildEvent<ScatterPointItem, SVGGraphicsElement>,
  'points' | 'ref' | 'children' | 'dangerouslySetInnerHTML' | 'fill'
>;

type InternalProps = BaseScatterSvgProps & ScatterInternalProps;

/**
 * @public
 */
export type Props<DataPointType = any, ValueAxisType = any> = BaseScatterSvgProps &
  ScatterProps<DataPointType, ValueAxisType>;

/**
 * Props after the fill object is split off: `fill` is the base color.
 */
type StringFillProps = Omit<Props, 'fill'> & { fill?: string };

const computeLegendPayloadFromScatterProps = (
  props: StringFillProps,
  explicitShape: ScatterCustomizedShape | undefined,
  fillObject: RechartsFill | undefined,
): ReadonlyArray<LegendPayload> => {
  const { dataKey, name, fill, stroke, legendType, hide } = props;
  return [
    {
      inactive: hide,
      dataKey,
      type: legendType,
      /*
       * Only an explicit shape describes the points to the legend, so that the legend of a Scatter
       * with the default shape stays unchanged. The legend symbol gets the same fill and stroke as the points,
       * so that a stroke-only shape (fill="none") stays visible in the legend.
       */
      dot: typeof explicitShape === 'string' ? { symbol: explicitShape, fill, stroke } : undefined,
      color: fill,
      fill: fillObject,
      value: getTooltipNameProp(name, dataKey),
      payload: props,
    },
  ];
};

type InputRequiredToComputeTooltipEntrySettings = {
  dataKey?: DataKey<any> | undefined;
  points?: ReadonlyArray<ScatterPointItem>;
  stroke?: string;
  strokeWidth?: number | string;
  fill?: string;
  name?: string;
  hide?: boolean;
  formatter?: Formatter;
  tooltipType?: TooltipType;
  id: GraphicalItemId;
};

const SetScatterTooltipEntrySettings = React.memo(
  ({
    dataKey,
    points,
    stroke,
    strokeWidth,
    fill,
    name,
    hide,
    formatter,
    tooltipType,
    id,
  }: InputRequiredToComputeTooltipEntrySettings) => {
    const tooltipEntrySettings: TooltipPayloadConfiguration = {
      dataDefinedOnItem: points?.map((p: ScatterPointItem) => p.tooltipPayload),
      getPosition: index => points?.[Number(index)]?.tooltipPosition,
      settings: {
        stroke,
        strokeWidth,
        fill,
        nameKey: undefined,
        dataKey,
        name: getTooltipNameProp(name, dataKey),
        hide,
        type: tooltipType,
        color: fill,
        unit: '', // why doesn't Scatter support unit?
        formatter,
        graphicalItemId: id,
      },
    };
    return <SetTooltipEntrySettings tooltipEntrySettings={tooltipEntrySettings} />;
  },
);

type ScatterSymbolsProps = ShapeAnimationProps & {
  points: ReadonlyArray<ScatterPointItem>;
  showLabels: boolean;
  allOtherScatterProps: InternalProps;
};

function ScatterLine({ points, props }: { points: NonEmptyArray<ScatterPointItem>; props: WithoutId<InternalProps> }) {
  const { line, lineType, lineJointType } = props;

  if (!line) {
    return null;
  }

  const scatterProps = svgPropertiesNoEvents(props);
  const customLineProps = svgPropertiesNoEventsFromUnknown(line);
  let linePoints: ReadonlyArray<NullableCoordinate>, lineItem: ReactNode;

  if (lineType === 'joint') {
    linePoints = points.map(entry => ({ x: entry.cx ?? null, y: entry.cy ?? null }));
  } else if (lineType === 'fitting') {
    const { xmin, xmax, a, b } = getLinearRegression(points);
    const linearExp = (x: number) => a * x + b;
    linePoints = [
      { x: xmin, y: linearExp(xmin) },
      { x: xmax, y: linearExp(xmax) },
    ];
  }

  const lineProps: CurveProps = {
    ...scatterProps,
    // @ts-expect-error customLineProps is contributing unknown props
    fill: 'none',
    // @ts-expect-error customLineProps is contributing unknown props
    stroke: scatterProps && scatterProps.fill,
    ...customLineProps,
    // @ts-expect-error linePoints is used before it is assigned (???)
    points: linePoints,
  };

  if (React.isValidElement(line)) {
    lineItem = React.cloneElement(line as any, lineProps);
  } else if (typeof line === 'function') {
    lineItem = line(lineProps);
  } else {
    lineItem = <Curve {...lineProps} type={lineJointType} />;
  }

  return (
    <Layer className="recharts-scatter-line" key="recharts-scatter-line">
      {lineItem}
    </Layer>
  );
}

/**
 * Resolves the color a scatter point actually renders with, mirroring the render order in ScatterSymbols:
 * data entry props win over the series props (theme already merged into those).
 * Cell is deprecated and intentionally not part of this; its colors never reach the tooltip.
 * Fill wins over stroke, same as Pie and Funnel entry colors.
 * https://github.com/recharts/recharts/issues/7976
 */
export function getScatterEntryColor(
  entry: unknown,
  seriesFill: string | undefined,
  seriesStroke: string | undefined,
  unthemedColors: UnthemedColors | undefined,
): string | undefined {
  /*
   * When the entry defines its own colors, the theme is suppressed for that entry at render time,
   * and the explicit Scatter props fill in the rest (see getEntryStyleOverrides).
   * Mirror that here so the tooltip color matches the rendered symbol.
   */
  const seriesFillFallback = hasOwnColors(entry) && unthemedColors != null ? unthemedColors.fill : seriesFill;
  const seriesStrokeFallback = hasOwnColors(entry) && unthemedColors != null ? unthemedColors.stroke : seriesStroke;
  const fill =
    entry != null && typeof entry === 'object' && 'fill' in entry && typeof entry.fill === 'string'
      ? entry.fill
      : undefined;
  const stroke =
    entry != null && typeof entry === 'object' && 'stroke' in entry && typeof entry.stroke === 'string'
      ? entry.stroke
      : undefined;
  return fill ?? seriesFillFallback ?? stroke ?? seriesStrokeFallback;
}

function ScatterLabelListProvider({
  showLabels,
  points,
  seriesFill,
  seriesStroke,
  unthemedColors,
  children,
}: {
  showLabels: boolean;
  points: ReadonlyArray<ScatterPointItem>;
  seriesFill: string | undefined;
  seriesStroke: string | undefined;
  unthemedColors: UnthemedColors | undefined;
  children: ReactNode;
}) {
  const chartViewBox = useViewBox();
  const labelColors: DataLabelColors = useMemo(
    () => ({
      hasFilledShapes: false,
      getShapeColors: (index: number) =>
        getEntryShapeColors(points[index]?.payload, seriesFill, seriesStroke, unthemedColors),
    }),
    [points, seriesFill, seriesStroke, unthemedColors],
  );
  const labelListEntries: ReadonlyArray<CartesianLabelListEntry> = useMemo(() => {
    return points?.map((point): CartesianLabelListEntry => {
      const viewBox: TrapezoidViewBox = {
        /*
         * Scatter label uses x and y as the reference point for the label,
         * not cx and cy.
         */
        x: point.x ?? 0,
        /*
         * Scatter label uses x and y as the reference point for the label,
         * not cx and cy.
         */
        y: point.y ?? 0,
        width: point.width,
        height: point.height,
        lowerWidth: point.width,
        upperWidth: point.width,
      };
      return {
        ...viewBox,
        /*
         * Here we put undefined because Scatter shows two values usually, one for X and one for Y.
         * LabelList will see this undefined and will use its own `dataKey` prop to determine which value to show,
         * using the payload below.
         */
        value: undefined,
        payload: point.payload,
        viewBox,
        parentViewBox: chartViewBox,
        fill: undefined,
      };
    });
  }, [chartViewBox, points]);

  return (
    <CartesianLabelListContextProvider value={showLabels ? labelListEntries : undefined}>
      <DataLabelColorsContextProvider value={labelColors}>{children}</DataLabelColorsContextProvider>
    </CartesianLabelListContextProvider>
  );
}

/**
 * Individual scatter point component that subscribes to its own isActive state.
 * This avoids re-rendering all points when the active index changes —
 * only the point becoming active and the point becoming inactive re-render.
 *
 * @param entry The scatter point data including coordinates, size, and tooltip payload
 * @param index The index of this point in the points array
 * @param shape The default shape to render for inactive points
 * @param activeShape The shape to render when this point is active, or undefined if no active shape
 * @param baseProps SVG presentation attributes (fill, stroke, etc.) shared across all points
 * @param entryStyleOverrides Removes theme styles from points that define their own colors in data, or undefined
 * @param themedActiveStyles Theme styles of the active shape, or undefined
 * @param id The graphical item ID of the parent Scatter component
 * @param restOfAllOtherProps Remaining Scatter props for user-provided event handlers via adaptEventsOfChild
 * @param onMouseEnterFromContext Curried mouse enter handler that dispatches tooltip activation
 * @param onMouseLeaveFromContext Curried mouse leave handler that dispatches tooltip deactivation
 * @param onClickFromContext Curried click handler that dispatches tooltip click activation
 */
function ScatterPoint({
  entry,
  paintFill,
  index,
  shape,
  activeShape,
  baseProps,
  entryStyleOverrides,
  themedActiveStyles,
  id,
  restOfAllOtherProps,
  animationElapsedTime,
  isAnimating,
  isEntrance,
  onMouseEnterFromContext,
  onMouseLeaveFromContext,
  onClickFromContext,
}: ShapeAnimationProps & {
  entry: ScatterPointItem;
  /**
   * `url(#…)` of the fill definition of the data entry, if it has its own fill object. Wins over the entry fill.
   */
  paintFill: string | undefined;
  index: number;
  shape: ScatterCustomizedShape;
  activeShape: ScatterCustomizedShape | undefined;
  baseProps: WithoutId<SVGPropsNoEvents<InternalProps>>;
  entryStyleOverrides: UnthemedColors | undefined;
  themedActiveStyles: ColorStyles2D | undefined;
  id: GraphicalItemId;
  restOfAllOtherProps: InternalProps;
  onMouseEnterFromContext: (
    data: ScatterPointItem,
    index: number,
  ) => (event: React.MouseEvent<SVGGraphicsElement>) => void;
  onMouseLeaveFromContext: (
    data: ScatterPointItem,
    index: number,
  ) => (event: React.MouseEvent<SVGGraphicsElement>) => void;
  onClickFromContext: (data: ScatterPointItem, index: number) => (event: React.MouseEvent<SVGGraphicsElement>) => void;
}): React.ReactElement {
  const hasActiveShape = activeShape != null && activeShape !== false;
  const selectIsActive = useMemo(() => {
    const strIndex = String(index);
    return (state: RechartsRootState): boolean => hasActiveShape && selectActiveTooltipIndex(state) === strIndex;
  }, [hasActiveShape, index]);
  const isActive: boolean = useAppSelector(selectIsActive) ?? false;

  // isActive is only true when hasActiveShape is true, so activeShape is defined here
  const option = isActive && activeShape != null && activeShape !== false ? activeShape : shape;
  // Filter out undefined values from baseProps so data fill/stroke aren't clobbered
  const filteredBaseProps: SVGProps<SVGGraphicsElement> = {
    ...(baseProps.fill !== undefined && { fill: baseProps.fill }),
    ...(baseProps.stroke !== undefined && { stroke: baseProps.stroke }),
    ...(baseProps.strokeWidth !== undefined && { strokeWidth: baseProps.strokeWidth }),
    ...(baseProps.strokeOpacity !== undefined && { strokeOpacity: baseProps.strokeOpacity }),
    ...(baseProps.fillOpacity !== undefined && { fillOpacity: baseProps.fillOpacity }),
    ...(baseProps.strokeDasharray !== undefined && { strokeDasharray: baseProps.strokeDasharray }),
  };
  const symbolProps: ScatterShapeProps = {
    ...filteredBaseProps,
    ...entryStyleOverrides,
    ...entry,
    ...(paintFill == null ? undefined : { fill: paintFill }),
    ...(isActive ? getActiveStyleOverrides(activeShape, themedActiveStyles, entry) : undefined),
    isActive,
    index,
    animationElapsedTime,
    isAnimating,
    isEntrance,
    [DATA_ITEM_GRAPHICAL_ITEM_ID_ATTRIBUTE_NAME]: String(id),
  };

  return (
    <ZIndexLayer
      /*
       * inactive Scatters use the parent zIndex, which is represented by undefined here.
       * ZIndexLayer will render undefined zIndex as-is, as regular children, without portals.
       * Active Scatters use the activeDot zIndex so they render above other elements.
       */
      zIndex={isActive ? DefaultZIndexes.activeDot : undefined}
    >
      <Layer
        className="recharts-scatter-symbol"
        {...adaptEventsOfChild(restOfAllOtherProps, entry, index)}
        onMouseEnter={onMouseEnterFromContext(entry, index)}
        onMouseLeave={onMouseLeaveFromContext(entry, index)}
        onClick={onClickFromContext(entry, index)}
      >
        <ScatterSymbol option={option} {...symbolProps} />
      </Layer>
    </ZIndexLayer>
  );
}

function ScatterSymbols(props: ScatterSymbolsProps) {
  const { points, allOtherScatterProps, animationElapsedTime, isAnimating, isEntrance } = props;
  const { shape, activeShape, dataKey, unthemedColors, themedActiveStyles } = allOtherScatterProps;
  const { id, ...allOtherPropsWithoutId } = allOtherScatterProps;

  const {
    onMouseEnter: onMouseEnterFromProps,
    onClick: onItemClickFromProps,
    onMouseLeave: onMouseLeaveFromProps,
    ...restOfAllOtherProps
  } = allOtherScatterProps;

  const onMouseEnterFromContext = useMouseEnterItemDispatch(onMouseEnterFromProps, dataKey, id);
  const onMouseLeaveFromContext = useMouseLeaveItemDispatch(onMouseLeaveFromProps);
  const onClickFromContext = useMouseClickItemDispatch(onItemClickFromProps, dataKey, id);
  if (!isNonEmptyArray(points)) {
    return null;
  }

  const svgProps: WithoutId<SVGPropsNoEvents<InternalProps>> = svgPropertiesNoEvents(allOtherPropsWithoutId);
  const baseProps: WithoutId<SVGPropsNoEvents<InternalProps>> =
    allOtherScatterProps.fillObject == null ? svgProps : { ...svgProps, fill: getFillUrl(getSeriesFillId(id)) };

  return (
    <>
      <ScatterLine points={points} props={allOtherPropsWithoutId} />
      {points.map((entry: ScatterPointItem, i: number) => (
        <ScatterPoint
          key={`symbol-${entry?.cx}-${entry?.cy}-${entry?.size}-${i}`}
          entry={entry}
          // a data entry with its own fill object paints with its own definition
          paintFill={readEntryFill(entry.payload).fillObject == null ? undefined : getFillUrl(getEntryFillId(id, i))}
          index={i}
          shape={shape}
          activeShape={activeShape}
          baseProps={baseProps}
          entryStyleOverrides={getEntryStyleOverrides(entry, unthemedColors)}
          themedActiveStyles={themedActiveStyles}
          id={id}
          restOfAllOtherProps={restOfAllOtherProps}
          animationElapsedTime={animationElapsedTime}
          isAnimating={isAnimating}
          isEntrance={isEntrance}
          onMouseEnterFromContext={onMouseEnterFromContext}
          onMouseLeaveFromContext={onMouseLeaveFromContext}
          onClickFromContext={onClickFromContext}
        />
      ))}
    </>
  );
}

const defaultScatterAnimateItems: AnimationInterpolateFn<ScatterPointItem, CartesianLayout> = (
  items,
  animationElapsedTime,
) => {
  if (items == null) return [];
  if (animationElapsedTime === 1) {
    return items.flatMap(item => (item.status === 'removed' ? [] : [item.next]));
  }
  return items.flatMap(item => {
    if (item.status === 'removed') return [];
    if (item.status === 'matched') {
      return [
        {
          ...item.next,
          cx: item.next.cx == null ? undefined : interpolate(item.prev.cx, item.next.cx, animationElapsedTime),
          cy: item.next.cy == null ? undefined : interpolate(item.prev.cy, item.next.cy, animationElapsedTime),
          size: interpolate(item.prev.size, item.next.size, animationElapsedTime),
        },
      ];
    }
    // added
    return [{ ...item.next, size: interpolate(0, item.next.size, animationElapsedTime) }];
  });
};

function SymbolsWithAnimation({
  previousPointsRef,
  props,
}: {
  previousPointsRef: MutableRefObject<ReadonlyArray<ScatterPointItem> | null>;
  props: InternalProps;
}) {
  const { points, isAnimationActive, animationBegin, animationDuration, animationEasing, animationInterpolateFn } =
    props;

  const { isAnimating, handleAnimationStart, handleAnimationEnd } = useAnimationCallbacks();
  const layout = useCartesianChartLayout();

  if (layout == null) return null;

  return (
    <ScatterLabelListProvider
      showLabels={!isAnimating}
      points={points}
      seriesFill={props.fill}
      seriesStroke={props.stroke}
      unthemedColors={props.unthemedColors}
    >
      <AnimatedItems
        animationInput={props}
        animationIdPrefix="recharts-scatter-"
        items={points}
        previousItemsRef={previousPointsRef}
        isAnimationActive={isAnimationActive}
        animationBegin={animationBegin}
        animationDuration={animationDuration}
        animationEasing={animationEasing}
        onAnimationStart={handleAnimationStart}
        onAnimationEnd={handleAnimationEnd}
        animationInterpolateFn={animationInterpolateFn}
        animationMatchBy={props.animationMatchBy}
        layout={layout}
      >
        {(stepData, animationElapsedTime, isEntrance) => (
          <Layer>
            <ScatterSymbols
              points={stepData}
              allOtherScatterProps={props}
              showLabels={!isAnimating}
              animationElapsedTime={animationElapsedTime}
              isAnimating={isAnimating || animationElapsedTime < 1}
              isEntrance={isEntrance}
            />
          </Layer>
        )}
      </AnimatedItems>
      {props.children}
      <LabelListFromLabelProp label={props.label} />
    </ScatterLabelListProvider>
  );
}

export function computeScatterPoints({
  displayedData,
  xAxis,
  yAxis,
  zAxis,
  scatterSettings,
  xAxisTicks,
  yAxisTicks,
  cells,
  layout,
  seriesFill,
  seriesStroke,
  unthemedColors,
}: {
  displayedData: ReadonlyArray<unknown>;
  xAxis: BaseAxisWithScale;
  yAxis: BaseAxisWithScale;
  zAxis: ZAxisWithScale | undefined;
  scatterSettings: ScatterSettings;
  xAxisTicks: ReadonlyArray<TickItem> | undefined;
  yAxisTicks: ReadonlyArray<TickItem> | undefined;
  cells: ReadonlyArray<ReactElement> | undefined;
  layout: LayoutType | undefined;
  seriesFill: string | undefined;
  seriesStroke: string | undefined;
  unthemedColors: UnthemedColors | undefined;
}): ReadonlyArray<ScatterPointItem> {
  /*
   * Scatter reads from two axes so it has two dataKeys.
   * On the value axis, the Scatter dataKey wins and the axis is the fallback - same as all other graphical items.
   * On the other axis, the axis dataKey wins.
   */
  const xAxisDataKey = getDataKeyOnAxis(scatterSettings.dataKey, xAxis.dataKey, layout, 'xAxis');
  const yAxisDataKey = getDataKeyOnAxis(scatterSettings.dataKey, yAxis.dataKey, layout, 'yAxis');
  const zAxisDataKey = zAxis && zAxis.dataKey;
  const defaultRangeZ = zAxis ? zAxis.range : implicitZAxis.range;
  const defaultZ = defaultRangeZ && defaultRangeZ[0];
  const xBandSize = xAxis.scale.bandwidth ? xAxis.scale.bandwidth() : 0;
  const yBandSize = yAxis.scale.bandwidth ? yAxis.scale.bandwidth() : 0;
  return displayedData.map((entry: unknown, index): ScatterPointItem => {
    const x: unknown = getValueByDataKey(entry, xAxisDataKey);
    const y: unknown = getValueByDataKey(entry, yAxisDataKey);
    const rawZ: unknown = getValueByDataKey(entry, zAxisDataKey);
    const z: unknown = isNullish(rawZ) || isNan(rawZ) ? '-' : rawZ;

    const pointColor = getScatterEntryColor(entry, seriesFill, seriesStroke, unthemedColors);
    const tooltipPayload: Array<TooltipPayloadEntry> = [
      {
        name: isNullish(xAxis.dataKey) ? scatterSettings.name : xAxis.name || String(xAxisDataKey),
        unit: xAxis.unit || '',
        // @ts-expect-error getValueByDataKey does not validate the output type
        value: x,
        payload: entry,
        dataKey: xAxisDataKey,
        type: scatterSettings.tooltipType,
        graphicalItemId: scatterSettings.id,
        color: pointColor,
        fill: pointColor,
      },
      {
        name: isNullish(yAxis.dataKey) ? scatterSettings.name : yAxis.name || String(yAxisDataKey),
        unit: yAxis.unit || '',
        // @ts-expect-error getValueByDataKey does not validate the output type
        value: y,
        payload: entry,
        dataKey: yAxisDataKey,
        type: scatterSettings.tooltipType,
        graphicalItemId: scatterSettings.id,
        color: pointColor,
        fill: pointColor,
      },
    ];

    if (z !== '-' && zAxis != null) {
      tooltipPayload.push({
        // @ts-expect-error name prop should not have dataKey in it
        name: zAxis.name || zAxis.dataKey,
        unit: zAxis.unit || '',
        // @ts-expect-error getValueByDataKey does not validate the output type
        value: z,
        payload: entry,
        dataKey: zAxisDataKey,
        type: scatterSettings.tooltipType,
        graphicalItemId: scatterSettings.id,
        color: pointColor,
        fill: pointColor,
      });
    }

    const cx: number | null = getCateCoordinateOfLine({
      axis: xAxis,
      ticks: xAxisTicks,
      bandSize: xBandSize,
      entry,
      index,
      dataKey: xAxisDataKey,
    });
    const cy = getCateCoordinateOfLine({
      axis: yAxis,
      ticks: yAxisTicks,
      bandSize: yBandSize,
      entry,
      index,
      dataKey: yAxisDataKey,
    });
    const size = z !== '-' && zAxis != null ? zAxis.scale.map(z) : defaultZ;
    const radius = size == null ? 0 : Math.sqrt(Math.max(size, 0) / Math.PI);

    /*
     * `id` from a data entry is never spread on rendered elements to avoid duplicate DOM ids.
     * The raw entry, id included, stays available through `payload`.
     */
    const entryWithoutId: Record<string, unknown> = typeof entry === 'object' && entry !== null ? { ...entry } : {};
    delete entryWithoutId.id;
    return withEntryFillColor<ScatterPointItem>(
      {
        ...entryWithoutId,
        cx,
        cy,
        x: cx == null ? undefined : cx - radius,
        y: cy == null ? undefined : cy - radius,
        width: 2 * radius,
        height: 2 * radius,
        size,
        node: { x, y, z },
        tooltipPayload,
        tooltipPosition: { x: cx, y: cy },
        payload: entry,
        ...(cells && cells[index] && cells[index].props),
      },
      entry,
    );
  });
}

const errorBarDataPointFormatter: ErrorBarDataPointFormatter<ScatterPointItem> = (
  dataPoint: ScatterPointItem,
  dataKey: Props['dataKey'],
  direction: ErrorBarDirection,
): ErrorBarDataItem => {
  return {
    x: dataPoint.cx,
    y: dataPoint.cy,
    value: direction === 'x' ? Number(dataPoint.node.x) : Number(dataPoint.node.y),
    // @ts-expect-error getValueByDataKey does not validate the output type
    errorVal: getValueByDataKey(dataPoint, dataKey),
  };
};

function ScatterWithId(props: InternalProps) {
  const { hide, points, className, needClip, xAxisId, yAxisId, id, fill, stroke, unthemedColors } = props;
  const previousPointsRef = useRef<ReadonlyArray<ScatterPointItem> | null>(null);
  if (hide) {
    return null;
  }
  const layerClass = clsx('recharts-scatter', className);
  const clipPathId = id;
  const clipPath = needClip ? `url(#clipPath-${clipPathId})` : undefined;
  const hasEntryFills = hasEntryFillObjects(points.map(point => point.payload));

  return (
    <ZIndexLayer zIndex={props.zIndex}>
      <Layer className={layerClass} clipPath={clipPath} id={id}>
        {(needClip || props.fillObject != null || hasEntryFills) && (
          <defs>
            {needClip && <GraphicalItemClipPath clipPathId={clipPathId} xAxisId={xAxisId} yAxisId={yAxisId} />}
            {props.fillObject != null && (
              <FillObjectDefinition id={getSeriesFillId(id)} fillObject={props.fillObject} color={fill} />
            )}
            {hasEntryFills && (
              <EntryFillDefinitions
                id={id}
                entries={points.map((point, index) => ({
                  index,
                  payload: point.payload,
                  color: getEntryShapeColors(point.payload, fill, stroke, unthemedColors).fill,
                }))}
              />
            )}
          </defs>
        )}
        <SetErrorBarContext
          xAxisId={xAxisId}
          yAxisId={yAxisId}
          data={points}
          dataPointFormatter={errorBarDataPointFormatter}
          errorBarOffset={0}
          clipPath={clipPath}
        >
          <Layer key="recharts-scatter-symbols">
            <SetLabelListClipArea xAxisId={xAxisId} yAxisId={yAxisId}>
              <SymbolsWithAnimation props={props} previousPointsRef={previousPointsRef} />
            </SetLabelListClipArea>
          </Layer>
        </SetErrorBarContext>
      </Layer>
    </ZIndexLayer>
  );
}

export const defaultScatterProps = {
  xAxisId: 0,
  yAxisId: 0,
  zAxisId: 0,
  label: false,
  line: false,
  legendType: 'circle',
  lineType: 'joint',
  lineJointType: 'linear',
  shape: 'circle',
  hide: false,

  isAnimationActive: 'auto',
  animationBegin: 0,
  animationDuration: 400,
  animationEasing: 'linear',
  animationMatchBy: matchAppend,
  animationInterpolateFn: defaultScatterAnimateItems,
  zIndex: DefaultZIndexes.scatter,
} as const satisfies Partial<Props>;

function ScatterImpl(
  props: WithIdRequired<StringFillProps> & Pick<InternalProps, 'unthemedColors' | 'themedActiveStyles' | 'fillObject'>,
) {
  const {
    animationBegin,
    animationDuration,
    animationEasing,
    hide,
    isAnimationActive,
    legendType,
    lineJointType,
    lineType,
    shape,
    xAxisId,
    yAxisId,
    zAxisId,
    ...everythingElse
  } = resolveDefaultProps(props, defaultScatterProps);

  const { needClip } = useNeedsClip(xAxisId, yAxisId);
  const cells = useMemo(() => findAllByType(props.children, Cell), [props.children]);
  const isPanorama = useIsPanorama();

  const points = useAppSelector(state => {
    return selectScatterPoints(
      state,
      xAxisId,
      yAxisId,
      zAxisId,
      props.id,
      cells,
      isPanorama,
      props.fill,
      props.stroke,
      props.unthemedColors,
    );
  });
  if (needClip == null) {
    return null;
  }
  if (points == null) {
    return null;
  }
  return (
    <>
      <SetScatterTooltipEntrySettings
        dataKey={props.dataKey}
        points={points}
        stroke={props.stroke}
        strokeWidth={props.strokeWidth}
        fill={props.fill}
        name={props.name}
        hide={props.hide}
        formatter={props.formatter}
        tooltipType={props.tooltipType}
        id={props.id}
      />
      <ScatterWithId
        {...everythingElse}
        xAxisId={xAxisId}
        yAxisId={yAxisId}
        zAxisId={zAxisId}
        lineType={lineType}
        lineJointType={lineJointType}
        legendType={legendType}
        shape={shape}
        hide={hide}
        isAnimationActive={isAnimationActive}
        animationBegin={animationBegin}
        animationDuration={animationDuration}
        animationEasing={animationEasing}
        points={points}
        needClip={needClip}
      />
    </>
  );
}

function ScatterFn(propsWithFillObject: Props) {
  const { color: fillColor, fillObject } = splitFill(propsWithFillObject.fill);
  // From here on, `fill` is the base color
  const outsideProps: StringFillProps = { ...propsWithFillObject, fill: fillColor };
  const effectiveDataKey = useEffectiveDataKey({
    dataKey: outsideProps.dataKey,
    xAxisId: outsideProps.xAxisId ?? defaultScatterProps.xAxisId,
    yAxisId: outsideProps.yAxisId ?? defaultScatterProps.yAxisId,
  });
  const graphicalItemThemeSelector = useGraphicalItemIdentity(effectiveDataKey, outsideProps);
  const themeFillObject = useGraphicalItemThemeFill(effectiveDataKey, outsideProps);
  const effectiveFillObject = fillObject ?? themeFillObject;
  const resolveLabelTheme = useSeriesLabelThemeResolver(graphicalItemThemeSelector);
  const unthemedColors = useUnthemedColors(outsideProps);
  const themedActiveStyles = useThemedActiveStyles(graphicalItemThemeSelector, outsideProps);
  const graphicalItemTheme = useBackwardsCompatibleTheme<StringFillProps>(
    graphicalItemThemeSelector,
    outsideProps,
    undefined,
  );
  const props = resolveDefaultProps(
    {
      ...outsideProps,
      // the legend shows the same symbol as the points, unless legendType says otherwise
      legendType: outsideProps.legendType ?? (typeof outsideProps.shape === 'string' ? outsideProps.shape : undefined),
      fill: outsideProps.fill ?? graphicalItemTheme?.fill,
      fillOpacity: outsideProps.fillOpacity ?? graphicalItemTheme?.fillOpacity,
      stroke: outsideProps.stroke ?? graphicalItemTheme?.stroke,
      strokeOpacity: outsideProps.strokeOpacity ?? graphicalItemTheme?.strokeOpacity,
      strokeWidth: outsideProps.strokeWidth ?? graphicalItemTheme?.strokeWidth,
      strokeDasharray:
        outsideProps.strokeDasharray ??
        (Array.isArray(graphicalItemTheme?.strokeDasharray)
          ? graphicalItemTheme.strokeDasharray.join(',')
          : graphicalItemTheme?.strokeDasharray),
    },
    defaultScatterProps,
  );
  const isPanorama = useIsPanorama();
  return (
    <RegisterGraphicalItemId id={props.id} type="scatter">
      {id => (
        <>
          <SetLegendPayload
            legendPayload={computeLegendPayloadFromScatterProps(props, outsideProps.shape, effectiveFillObject)}
          />
          <SetCartesianGraphicalItem
            type="scatter"
            id={id}
            data={props.data}
            xAxisId={props.xAxisId}
            yAxisId={props.yAxisId}
            zAxisId={props.zAxisId}
            dataKey={props.dataKey}
            hide={props.hide}
            name={props.name}
            tooltipType={props.tooltipType}
            isPanorama={isPanorama}
          />
          <DataLabelThemeContextProvider value={resolveLabelTheme}>
            <ScatterImpl
              {...props}
              id={id}
              fillObject={effectiveFillObject}
              unthemedColors={unthemedColors}
              themedActiveStyles={themedActiveStyles}
            />
          </DataLabelThemeContextProvider>
        </>
      )}
    </RegisterGraphicalItemId>
  );
}

/**
 * @provides LabelListContext
 * @provides ErrorBarContext
 * @provides CellReader
 * @consumes CartesianChartContext
 * @public
 */
export const Scatter = React.memo(ScatterFn, propsAreEqual) as {
  <DataPointType = any, ValueAxisType = any>(props: Props<DataPointType, ValueAxisType>): ReactElement;
  (props: Props<any, any>): ReactElement;
};
// @ts-expect-error we need to set the displayName for debugging purposes

Scatter.displayName = 'Scatter';
